#include <zephyr/kernel.h>
#include <zephyr/rtio/rtio_work.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/slist.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(rtio_work, CONFIG_RTIO_WORK_LOG_LEVEL);

static void rtio_work_req_k_work_handler(struct k_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);

	if (req->handler) {
		req->handler(req->arg);
	}
}

void rtio_work_req_init(struct rtio_work_req *req, rtio_work_handler_t handler, void *arg)
{
	__ASSERT_NO_MSG(req != NULL);

	k_work_init(&req->work, rtio_work_req_k_work_handler);
	req->handler = handler;
	req->arg = arg;
}

int rtio_work_req_submit(struct rtio_work_req *req)
{
	if (req == NULL) {
		LOG_ERR("Attempted to submit a NULL rtio_work_req");
		return -EINVAL;
	}

	return k_work_submit(&req->work);
}
